  var ALIAS = {"NLRTM-NLMVII": "APMT APM 2 MV2 MVII Maasvlakte II", "NLRTM-DCD": "ECT Delta Hutchison", "NLRTM-RWG": "RWG MV2 Maasvlakte II", "NLRTM-EMX": "Euromax", "BEANR-K1742": "MPET 1742 Deurganckdok", "BEANR-K1718": "MPET 1718 Deurganckdok", "BEANR-K913": "PSA 913 Noordzee", "BEANR-K869": "PSA 869 Europa", "BEANR-1700": "DP World AGT 1700 Antwerp Gateway"};
  var REGION = { BE: 0, NL: 0, DE: 1, LU: 1, FR: 1, CH: 1 };   // свой регион выше в результатах поиска
  var byCode = {};
  ROWS.forEach(function (r) { byCode[r[0]] = r; });
  function obj(r) { return r && { code: r[0], term: r[1], name: r[2], operator: r[3], city: r[4], cc: r[5], lat: r[6], lon: r[7], address: r[8], web: r[9], remarks: r[10], kind: r[11], source: r[12] }; }
  function norm(s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }
  function hay(r) { return norm(r[0] + ' ' + r[1] + ' ' + r[2] + ' ' + r[3] + ' ' + r[4] + ' ' + r[8] + ' ' + r[10] + ' ' + (ALIAS[r[0]] || '')); }
  // порядок: точный причал → все слова в названии/синонимах → свой регион (BE/NL, затем соседи) → короче название
  function rank(r, toks) {
    var g = REGION[r[5]], t = norm(r[1]), nm = norm(r[2] + ' ' + (ALIAS[r[0]] || ''));
    var berth = toks.length === 1 && (t === toks[0] || t === 'k' + toks[0]) ? 0 : 1;
    var inName = toks.every(function (x) { return nm.indexOf(x) >= 0; }) ? 0 : 1;
    return berth * 100000 + inName * 10000 + (g == null ? 2 : g) * 1000 + r[2].length;
  }
  function match(q) { var toks = norm(q).split(/\s+/).filter(Boolean); if (!toks.length) return [];
    return ROWS.filter(function (r) { var h = hay(r); return toks.every(function (t) { return h.indexOf(t) >= 0; }); })
      .map(function (r) { return [rank(r, toks), r]; }).sort(function (a, b) { return a[0] - b[0]; }).map(function (x) { return x[1]; }); }
  return {
    count: ROWS.length,
    all: function () { return ROWS.map(obj); },
    get: function (code) { return obj(byCode[String(code || '').trim().toUpperCase()]); },
    // номер причала / код SMDG: «1742», «K913», «NLMVII»
    berth: function (q) {
      var n = norm(q).trim(); if (!n) return null;
      var r = ROWS.filter(function (r) { var t = norm(r[1]); return t === n || t === 'k' + n; }).sort(function (a, b) { return rank(a, [n]) - rank(b, [n]); })[0];
      return obj(r);
    },
    // по коду, причалу или названию: «ECT Delta», «APM 2», «Swissterminal Basel»
    find: function (q) { return this.get(q) || this.berth(q) || obj(match(q)[0]); },
    search: function (q, limit) { return match(q).slice(0, limit || 500).map(obj); }
  };
